def transform(grid):
    h, w = len(grid), len(grid[0])
    clues = [(r, c, grid[r][c]) for r in range(h) for c in range(w) if grid[r][c]]
    if not clues:
        return [row[:] for row in grid]

    # Clues identify a repeating color sequence on one of the two diagonal
    # directions. Prefer the shortest fully specified repeating pattern.
    candidates = []
    for axis, coord in enumerate((lambda r, c: c-r, lambda r, c: r+c)):
        for period in range(1, 2 * max(h, w) + 2):
            colors = {}
            for r, c, color in clues:
                residue = coord(r, c) % period
                if residue in colors and colors[residue] != color:
                    break
                colors[residue] = color
            else:
                if len(colors) == period:
                    candidates.append((period, axis, coord, colors))
                    break
    if not candidates:
        return [row[:] for row in grid]
    period, _, coord, colors = min(candidates, key=lambda x: (x[0], x[1]))
    return [[colors[coord(r, c) % period] for c in range(w)] for r in range(h)]
